      c.translate(cx, ty); c.scale(Math.max(0.02, Math.sin(e * Math.PI / 2)), 1);
      c.fillStyle = rainbow(-tw / 2, tw / 2, tilt * 0.5);
      c.fillText(api.text, 0, 0, W * 0.9);
      // diffraction grating + shine sweep, painted only onto the lettering
