        for (var k = 0; k < 16; k++) { var a = k * Math.PI / 8 + seed, r0 = 16 + (1 - burst) * 40, r1 = r0 + 18 + burst * 30; c.beginPath(); c.moveTo(Math.cos(a) * r0, Math.sin(a) * r0); c.lineTo(Math.cos(a) * r1, Math.sin(a) * r1); c.stroke(); }
        c.restore();
