    var u = x / Math.max(1, W);
    var h = N(u * fr + seed + i * 7.3, i * 3.1) * 0.75 + N(u * fr * 3 + i, seed) * 0.25;
    var y = H * (base - amp * (h - 0.3) * 2.2);
