    for (var k = 0; k < 3; k++) { var yy = y - s * 0.2 - k * s * 0.32, ww = s * (0.42 - k * 0.1);
      g.fillStyle = dark; g.beginPath(); g.moveTo(x - ww, yy); g.lineTo(x, yy - s * 0.55); g.lineTo(x + ww, yy); g.closePath(); g.fill();
