        for (var k = 0; k < n; k++) { var gx = R() * W, gy0 = hillY(i, gx), gy = gy0 + Math.pow(R(), 1.6) * (H - gy0) * (i === 4 ? 1 : 0.5), d = depth(gy);
          g.strokeStyle = R() < 0.5 ? api.rgba('#c9f07a', 0.10 + d * 0.12) : api.rgba('#06180f', 0.22); g.lineWidth = 0.6 + d;
