        for (var t = 0; t < cnt; t++) { var tx = R() * W, ty = hillY(i, tx) + 2 + R() * H * 0.02 * i, s = (4 + R() * 5) * (0.6 + depth(ty) * 2.2);
          if (Math.abs(tx - wfX) < W * 0.03) continue;
