    var img = sc.getImageData(0, 0, src.width, src.height).data, sw = src.width;
    bottoms = [];
    for (var x = 0; x < sw; x += 2) {
      var b = -1; for (var yy = Math.min(src.height - 1, Math.ceil(bot + 4)); yy > top; yy--) { if (img[(yy * sw + x) * 4 + 3] > 200) { b = yy; break; } }
      bottoms.push(b);
    }
